// Extract generated text from Gemini response
const response = $input.item.json;
const generatedText = response.candidates[0].content.parts[0].text;

// Get form data
const formData = $('Google Sheets Trigger').item.json;

// Create HTML content with proper formatting
const htmlContent = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    @page {
      margin: 1in;
      size: A4;
    }
    body {
      font-family: 'Times New Roman', serif;
      font-size: 12pt;
      line-height: 1.5;
      color: #000;
    }
    h1 {
      font-size: 18pt;
      font-weight: bold;
      text-align: center;
      margin-top: 0;
      margin-bottom: 24pt;
    }
    h2 {
      font-size: 14pt;
      font-weight: bold;
      margin-top: 18pt;
      margin-bottom: 12pt;
    }
    h3 {
      font-size: 12pt;
      font-weight: bold;
      margin-top: 12pt;
      margin-bottom: 6pt;
    }
    p {
      margin-bottom: 12pt;
      text-align: justify;
    }
    .title-page {
      text-align: center;
      margin-top: 100pt;
    }
    .metadata {
      margin-top: 50pt;
      text-align: center;
      line-height: 2;
    }
  </style>
</head>
<body>
  <div class="title-page">
    <h1>${formData['Capstone Title']}</h1>
    <div class="metadata">
      <p><strong>Submitted by:</strong><br>${formData['Student Name(s)']}</p>
      <p><strong>Registration Number:</strong><br>${formData['Registration Number(s)']}</p>
      <p><strong>Course:</strong><br>${formData['Course Name and Code']}</p>
      <p><strong>Supervisor:</strong><br>${formData['Supervisor/Advisor Name']}</p>
      <p><strong>Date:</strong><br>${formData['Date of Submission']}</p>
    </div>
  </div>
  <div style="page-break-before: always;"></div>
  ${generatedText.replace(/#{1,6}\s/g, match => {
    const level = match.trim().length;
    return level === 1 ? '<h1>' : level === 2 ? '<h2>' : '<h3>';
  }).replace(/\n\n/g, '</p><p>').replace(/^(?!<h)/gm, '<p>').replace(/$(?!<\/h)/gm, '</p>')}
</body>
</html>
`;

return {
  json: {
    htmlContent: htmlContent,
    fileName: `${formData['Capstone Title'].replace(/[^a-z0-9]/gi, '_')}_${formData['Registration Number(s)'].replace(/[^a-z0-9]/gi, '_')}.pdf`,
    userEmail: formData['User Email'],
    capstoneTitle: formData['Capstone Title']
  }
};
